"""Generates fnv_names.c (spec 15.6 fixture): 64 record names hashed with FNV-1a 64, plus a colliding pair.

The pair was found with find_fnv_collision.c (a rho search); this script re-checks that both names really hash to the same
value before writing. usage: python tests/fixtures/gen_fnv_names.py   (rewrites fnv_names.c next to this file)
"""

from __future__ import annotations

from pathlib import Path

GROUPS = ["player", "enemy", "item", "quest"]
FIELDS = ["health", "armor", "speed", "damage", "mana", "level", "xp", "gold",
          "range", "cooldown", "weight", "value", "state", "target", "timer", "flags"]
COLLISION = ("rec_L9qap7cOoK1", "rec_EQI_EyPfCio")
COLLISION_ID = 100


def fnv1a64(text: str) -> int:
    value = 14695981039346656037
    for byte in text.encode():
        value = ((value ^ byte) * 1099511628211) & 0xFFFFFFFFFFFFFFFF
    return value


def records() -> list[tuple[str, int, int]]:
    """(name, hash, id) for the 64 ordinary record names; ids are 1..64."""
    names = ["%s.%s" % (g, f) for g in GROUPS for f in FIELDS]
    return [(name, fnv1a64(name), index + 1) for index, name in enumerate(names)]


def render() -> str:
    rows = records()
    if len({h for _n, h, _i in rows}) != 64:
        raise SystemExit("ordinary names collide")
    a, b = COLLISION
    if fnv1a64(a) != fnv1a64(b) or a == b:
        raise SystemExit("the colliding pair does not collide")
    out = ['/* GENERATED by gen_fnv_names.py; do not edit. Spec 15.6 fixture (docs/trace-fixtures.md).',
           '   usage: fnv_names.exe',
           '   Records are named by FNV-1a 64 (offset 14695981039346656037, prime 1099511628211). fx_dispatch_record',
           '   switches on the hash constants (the names are not compared there), so the code holds bare 64-bit',
           '   constants and the name strings live in g_names. The names "%s" and "%s" hash to the same value' % COLLISION,
           '   0x%016x: fx_dispatch_record has one case for it (id %d). */' % (fnv1a64(COLLISION[0]), COLLISION_ID),
           '#include "trace_common.h"', '',
           'typedef unsigned __int64 u64;', '',
           'FX u64 fx_fnv1a64(const char *text) {',
           '    u64 hash = 14695981039346656037ull;',
           '    for (; *text; ++text) { hash ^= (unsigned char)*text; hash *= 1099511628211ull; }',
           '    return hash;', '}', '',
           'static const char *const g_names[64] = {']
    out += ['    "%s",' % name for name, _h, _i in rows]
    out += ['};', '', 'static const char *const g_collision[2] = { "%s", "%s" };' % COLLISION, '',
            '/* Record id for a hash; 0 when unknown. */',
            'FX int fx_dispatch_record(u64 hash) {', '    switch (hash) {']
    out += ['    case 0x%016xull: return %d;' % (h, i) for _n, h, i in rows]
    out += ['    case 0x%016xull: return %d;' % (fnv1a64(COLLISION[0]), COLLISION_ID),
            '    default: return 0;', '    }', '}', '',
            'int main(void) {',
            '    int known = 0;',
            '    fx_arm_watchdog(20);',
            '    for (int i = 0; i < 64; ++i) {',
            '        u64 hash = fx_fnv1a64(g_names[i]);',
            '        int id = fx_dispatch_record(hash);',
            '        known += id == i + 1;',
            '        say("record name=%s hash=0x%016I64x id=%d", g_names[i], hash, id);',
            '    }',
            '    u64 ha = fx_fnv1a64(g_collision[0]), hb = fx_fnv1a64(g_collision[1]);',
            '    say("collision a=%s b=%s hash_a=0x%016I64x hash_b=0x%016I64x same=%d id=%d",',
            '        g_collision[0], g_collision[1], ha, hb, ha == hb, fx_dispatch_record(ha));',
            '    say("known=%d", known);',
            '    return known == 64 && ha == hb ? 0 : 1;', '}', '']
    return "\n".join(out)


if __name__ == "__main__":
    (Path(__file__).resolve().parent / "fnv_names.c").write_text(render(), newline="\n")
